        "quote": "想自伤/伤人、明显激越失控、冲出家门"
      },
      {
        "event_id": "lite_evt_00019",
        "explanation": "Cardiac information was visible to the doctor, but the trajectory did not complete the required cardiac red-flag stratification.",
        "quote": "窦性心律不齐"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00151",
        "explanation": "The doctor adapted language and behavior to avoid worsening the patient's fear of control.",
        "quote": "先不要跟她解释“住不住院、是不是关起来”"
      },
      {
        "event_id": "lite_evt_00194",
        "explanation": "The doctor coached the family on low-stimulation positioning and interaction during ED observation.",
        "quote": "你就稍微拉开一点距离"
      }
    ]
  },
