          "quote": "患者今天刚从你们科出院"
        },
        {
          "event_id": "lite_evt_00343",
          "explanation": "The doctor designed a practical caregiver-rest and contact plan during hospital boarding.",
          "quote": "你手机开铃声"
        }
      ],
      "completion": "complete",
      "explanation": "The model navigated blurred records, caregiver fatigue, family conflict, hospital boarding, and practical contact/coverage logistics with concrete steps.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
